-- BookEasy demo data for Tamil Nadu (Chennai, Coimbatore, Madurai, Thoothukudi, Tiruchirappalli, Salem).
-- GENERATED by backend/seed/generate_demo_data.py - edit the script, not this file.
-- All businesses, people and reviews are fictional. Demo logins: demo.*@example.com / Demo@1234
-- Safe to re-run: earlier demo rows are removed first. DO NOT run against production.
SET NAMES utf8mb4;
START TRANSACTION;

-- Remove earlier demo data
CREATE TEMPORARY TABLE demo_users AS SELECT id FROM users WHERE email LIKE 'demo.%@example.com';
CREATE TEMPORARY TABLE demo_orgs AS SELECT o.id FROM organizations o JOIN organization_owners oo ON oo.organization_id = o.id WHERE oo.user_id IN (SELECT id FROM demo_users);
DELETE FROM reviews WHERE organization_id IN (SELECT id FROM demo_orgs) OR customer_id IN (SELECT id FROM demo_users);
DELETE FROM appointments WHERE organization_id IN (SELECT id FROM demo_orgs) OR customer_id IN (SELECT id FROM demo_users);
DELETE FROM organizations WHERE id IN (SELECT id FROM demo_orgs);
DELETE FROM users WHERE id IN (SELECT id FROM demo_users);
DELETE FROM uploaded_files WHERE storage_key LIKE 'public/demo/%';
DROP TEMPORARY TABLE demo_users;
DROP TEMPORARY TABLE demo_orgs;

-- ID offsets so demo rows never collide with real ones
SET @u = (SELECT COALESCE(MAX(id), 0) FROM users);
SET @o = (SELECT COALESCE(MAX(id), 0) FROM organizations);
SET @b = (SELECT COALESCE(MAX(id), 0) FROM organization_branches);
SET @s = (SELECT COALESCE(MAX(id), 0) FROM services);
SET @st = (SELECT COALESCE(MAX(id), 0) FROM staff_profiles);
SET @a = (SELECT COALESCE(MAX(id), 0) FROM appointments);
SET @r = (SELECT COALESCE(MAX(id), 0) FROM reviews);
















SET @f = (SELECT COALESCE(MAX(id), 0) FROM uploaded_files);

