-- Recalculate each demo business's rating from its reviews
UPDATE organizations o JOIN (SELECT organization_id, ROUND(AVG(rating), 2) avg_r, COUNT(*) n FROM reviews WHERE status = 'VISIBLE' GROUP BY organization_id) r ON r.organization_id = o.id SET o.rating_avg = r.avg_r, o.review_count = r.n WHERE o.id > @o;

